css:
@page { size: Letter; margin: 12mm 12mm 14mm; }
.axiom-report { color:#1d2c3d; font-family:Arial,Helvetica,sans-serif; font-size:9pt; line-height:1.35; }
.axiom-report * { box-sizing:border-box; }
.axiom-header { background:#112d4a; color:#fff; padding:15px 18px; display:table; width:100%; }
.axiom-brand { display:table-cell; width:115px; vertical-align:middle; }
.axiom-brand img { width:100px; height:100px; object-fit:contain; }
.axiom-title { display:table-cell; vertical-align:middle; padding-left:16px; }
.axiom-eyebrow { color:#a8c7e9; font-size:8pt; letter-spacing:1.2px; font-weight:bold; }
.axiom-title h1 { font-size:21pt; line-height:1.1; margin:6px 0; color:#fff; }
.axiom-number { font-size:10pt; font-weight:bold; color:#fff; }
.axiom-number span { font-size:8pt; font-weight:normal; margin-left:12px; color:#c9d9ea; }
.axiom-status { background:#eaf3fb; border-bottom:2px solid #0877d6; padding:8px 12px; display:table; width:100%; }
.axiom-status span { display:table-cell; width:33%; padding-right:8px; }
.axiom-status strong { display:block; color:#43617e; font-size:7.5pt; text-transform:uppercase; }
.axiom-section { margin-top:15px; }
.axiom-section h2 { color:#123d65; border-bottom:1px solid #a9cce8; padding-bottom:4px; margin:0 0 7px; font-size:11pt; page-break-after:avoid; }
.axiom-info,.axiom-table { width:100%; border-collapse:collapse; table-layout:fixed; }
.axiom-info th,.axiom-info td { padding:5px 6px; border-bottom:1px solid #e1e9f0; vertical-align:top; overflow-wrap:anywhere; }
.axiom-info th { text-align:left; color:#536a80; font-weight:bold; width:17%; }
.axiom-info td { width:33%; }
.axiom-table th { background:#dcecf9; text-align:left; color:#153c62; font-size:8pt; padding:6px; border-bottom:1px solid #a9cce8; }
.axiom-table td { padding:6px; border-bottom:1px solid #e1e9f0; vertical-align:top; overflow-wrap:anywhere; }
.axiom-table thead { display:table-header-group; }
.axiom-table tr { page-break-inside:avoid; }
.axiom-right { text-align:right !important; white-space:nowrap; }
.axiom-narrative { overflow-wrap:anywhere; }
.axiom-narrative p { margin:0 0 5px; }
.axiom-narrative ul,.axiom-narrative ol { margin:3px 0 6px; padding-left:18px; }
.axiom-plain { white-space:pre-wrap; }
.axiom-empty { color:#6c7f91; font-style:italic; margin:4px 0; }
.axiom-totals { text-align:right; background:#f1f6fa; padding:8px; margin-top:3px; }
.axiom-totals span { margin-left:20px; }
.axiom-totals strong { color:#123d65; }
.axiom-signoff { page-break-inside:avoid; }
.axiom-signatures { display:table; width:100%; }
.axiom-signatures > div { display:table-cell; width:50%; padding-right:20px; vertical-align:bottom; }
.axiom-signature-line { height:55px; border-bottom:1px solid #75899c; margin-bottom:5px; }
.axiom-signature-line img { max-height:50px; max-width:200px; }
.axiom-signatures strong { color:#123d65; }
.axiom-footer { margin-top:18px; padding-top:5px; border-top:1px solid #d5e1ed; color:#678098; font-size:8pt; }
.axiom-time-section { page-break-inside:avoid; break-inside:avoid-page; }
